@layer moduix.components {
  .root {
    display: inline-flex;
    flex-direction: column;
    gap: var(--moduix-rating-group-root-gap, var(--moduix-spacing-1));
    color: var(--moduix-rating-group-color, var(--moduix-color-muted-foreground));

    &[data-size='xs'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-xs, var(--moduix-spacing-3-5));
    }

    &[data-size='sm'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-sm, var(--moduix-spacing-4));
    }

    &[data-size='md'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-md, var(--moduix-spacing-5));
    }

    &[data-size='lg'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-lg, var(--moduix-spacing-6));
    }

    &[data-size='xl'] {
      --_rating-group-icon-size: var(--moduix-rating-group-icon-size-xl, var(--moduix-spacing-7));
    }
  }

  .label {
    color: var(--moduix-rating-group-label-color, var(--moduix-color-foreground));
    font-size: var(--moduix-rating-group-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-rating-group-label-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-rating-group-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;

    &[data-disabled] {
      opacity: var(--moduix-rating-group-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .control {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-rating-group-gap, var(--moduix-spacing-1));

    &[data-disabled] {
      opacity: var(--moduix-rating-group-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .item {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--moduix-radius-sm);
    color: inherit;
    line-height: 0;
    cursor: pointer;
    transition:
      color var(--moduix-rating-group-transition, var(--moduix-transition-default)),
      opacity var(--moduix-rating-group-transition, var(--moduix-transition-default));

    &[data-readonly],
    &[data-disabled] {
      cursor: default;
    }

    &[data-disabled] {
      pointer-events: none;
    }

    &:focus-visible {
      outline: var(
          --moduix-rating-group-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-rating-group-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-rating-group-focus-ring-offset, var(--moduix-border-width-sm));
    }
  }

  .itemIndicator {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(
      --_rating-group-icon-size,
      var(--moduix-rating-group-icon-size-md, var(--moduix-spacing-5))
    );
    height: var(
      --_rating-group-icon-size,
      var(--moduix-rating-group-icon-size-md, var(--moduix-spacing-5))
    );
    color: var(--moduix-rating-group-active-color, var(--moduix-color-primary));

    & > svg {
      flex: none;
      width: 100%;
      height: 100%;
      transition:
        color var(--moduix-rating-group-transition, var(--moduix-transition-default)),
        fill var(--moduix-rating-group-transition, var(--moduix-transition-default)),
        stroke var(--moduix-rating-group-transition, var(--moduix-transition-default)),
        clip-path var(--moduix-rating-group-transition, var(--moduix-transition-default));
    }

    &[data-half] .iconFg {
      clip-path: inset(0 50% 0 0);
    }

    &:not([data-highlighted]) .iconFg {
      clip-path: inset(0 100% 0 0);
    }
  }

  .root:dir(rtl) {
    .itemIndicator[data-half] .iconFg {
      clip-path: inset(0 0 0 50%);
    }
  }

  .iconBg {
    position: absolute;
    inset: 0;
    color: var(--moduix-rating-group-color, var(--moduix-color-muted-foreground));
    fill: transparent;
    stroke: currentColor;
  }

  .iconFg {
    position: absolute;
    inset: 0;
    color: var(--moduix-rating-group-active-color, var(--moduix-color-primary));
    fill: currentColor;
    stroke: currentColor;
    clip-path: inset(0 0 0 0);
  }
}

import {
  RatingGroupContext,
  RatingGroupHiddenInput,
  RatingGroupItemContext,
  useRatingGroup,
  useRatingGroupContext,
  useRatingGroupItemContext,
} from '@ark-ui/vue/rating-group';
import RatingGroup from './RatingGroup.vue';
import RatingGroupControl from './RatingGroupControl.vue';
import RatingGroupItem from './RatingGroupItem.vue';
import RatingGroupItemIndicator from './RatingGroupItemIndicator.vue';
import RatingGroupItems from './RatingGroupItems.vue';
import RatingGroupLabel from './RatingGroupLabel.vue';
import RatingGroupRootProvider from './RatingGroupRootProvider.vue';

export {
  RatingGroup,
  RatingGroupContext,
  RatingGroupControl,
  RatingGroupHiddenInput,
  RatingGroupItem,
  RatingGroupItemContext,
  RatingGroupItemIndicator,
  RatingGroupItems,
  RatingGroupLabel,
  RatingGroupRootProvider,
  useRatingGroup,
  useRatingGroupContext,
  useRatingGroupItemContext,
};

export type {
  RatingGroupContextProps,
  RatingGroupControlBaseProps,
  RatingGroupControlProps,
  RatingGroupHiddenInputBaseProps,
  RatingGroupHiddenInputProps,
  RatingGroupHoverChangeDetails,
  RatingGroupItemBaseProps,
  RatingGroupItemContextProps,
  RatingGroupItemProps,
  RatingGroupLabelBaseProps,
  RatingGroupLabelProps,
  RatingGroupRootBaseProps,
  RatingGroupRootEmits,
  RatingGroupRootProviderBaseProps,
  RatingGroupValueChangeDetails,
  UseRatingGroupContext,
  UseRatingGroupItemContext,
  UseRatingGroupProps,
  UseRatingGroupReturn,
} from '@ark-ui/vue/rating-group';

export type { RatingGroupRootProps, RatingGroupSize } from './RatingGroup.vue';
export type { RatingGroupRootProviderProps } from './RatingGroupRootProvider.vue';
export type { RatingGroupItemIndicatorProps } from './RatingGroupItemIndicator.vue';
